const items = $input.all();
let text = items[0]?.json?.output || '';

// Limpiar markdown
text = text.trim();
text = text.replace(/```[\s\S]*?```/g, '');
text = text.replace(/[*_#>`]/g, '');
text = text.replace(/\s+/g, ' ').trim();

return [{ json: { text } }];

const agentOutput = $('AI Agent1').first().json.output || '';

// La notificación la arma el backend a partir de los campos configurados
// (GET /n8n/lead/{whatsapp}/resumen). Antes las etiquetas y emojis estaban
// acá a mano, así que un campo nuevo nunca aparecía.
const notif = $('Resumen lead backend').first().json.data || '';

const textoLead = agentOutput.replace('##LISTO_PARA_CERRAR##', '').trim();

return [{ json: { texto_lead: textoLead, notif_encargado: notif } }];

const fromMe = $('Normalizacion').first().json.message.from_me;
const chatId = $('Normalizacion').first().json.message.chat_id.replace('@s.whatsapp.net','');
const encargadoNumero = '5492615254816';

let origen = '';

if (chatId === encargadoNumero) {
  origen = 'ENCARGADO_COMANDO';
} else if (fromMe === true || fromMe === 'true') {
  origen = 'ENCARGADO_AL_LEAD';
} else {
  origen = 'LEAD';
}

return [{ json: { ...$input.first().json, origen } }];

const lead = $json;
const config = $('Leer config backend').first().json;

const nombre = lead.nombre || 'cliente';
const empresa = config.nombre_empresa || 'nosotros';
const plantilla = config.mensaje_seguimiento || 'Hola {nombre}, te contactamos desde {empresa}. ¿Pudiste ver la info?';

const mensaje = plantilla
  .replace('{nombre}', nombre)
  .replace('{empresa}', empresa);

return [{
  json: {
    ...lead,
    mensaje_seguimiento: mensaje,
    encargado_numero: config.encargado_numero,
    server_url: config.server_url || '',
    instance_name: config.instance_name || '',
    apikey: config.apikey || ''
  }
}];

const lead = $('Preparar mensaje seguimiento').item.json;
const nombre = lead.nombre || 'Sin nombre';
const whatsapp = lead.whatsapp || '';

const notif = `⏰ Seguimiento enviado:\n👤 ${nombre}\n📱 ${whatsapp}\n\nEl lead pasó a modo HUMANO. Esperando tu contacto.`;

return [{ json: { text: notif, encargado_numero: lead.encargado_numero } }];
